PLAN='/app/submissions/initial_plan.csv'
trips={r['trip_id']:r for r in csv.DictReader(open(f'{DATA}/trips.csv'))}
buses={r['bus_id']:r for r in csv.DictReader(open(f'{DATA}/buses.csv'))}
dead={(r['from_location'],r['to_location']):int(r['minutes']) for r in csv.DictReader(open(f'{DATA}/deadhead_times.csv'))}
reserves=list(csv.DictReader(open(f'{DATA}/reserve_requirements.csv')))
rows=list(csv.DictReader(open(PLAN)))
issues=[]
if any(r['row_type']"'!='"'trip' for r in rows):
    issues.append('non-trip row present in zero-charge incumbent')
for idx,r in enumerate(rows, start=2):
    if r['item_id']"'!='"'': issues.append(f'line {idx} trip item_id not blank')
    if r['decision'] not in {'operate','cancel'}: issues.append(f'line {idx} invalid decision')
    if any(r[k] for k in ['charger_id','start_min','end_min','energy_kwh']): issues.append(f'line {idx} trip charge fields not blank')
    if r['decision']=='cancel' and r['bus_id']"'!='"'': issues.append(f'line {idx} canceled trip bus not blank')
by_bus=defaultdict(list)
for r in rows:
    if r['decision']=='operate':
        by_bus[r['bus_id']].append(trips[r['trip_id']])
for b, seq in by_bus.items():
    seq.sort(key=lambda x:int(x['depart_min']))
    loc='DEPOT'; tm=0; soc=float(buses[b]['initial_soc_kwh'])
    for t in seq:
        if tm + dead[(loc,t['start_location'])] > int(t['depart_min']):
            issues.append(f'timing {b} {t[\"trip_id\"]}')
        if soc + 1e-8 < float(t['min_start_soc_kwh']):
            issues.append(f'start soc {b} {t[\"trip_id\"]}')
        soc -= float(t['energy_kwh'])
        if soc + 1e-8 < float(buses[b]['min_soc_kwh']):
            issues.append(f'min soc {b} {t[\"trip_id\"]}')
        tm=int(t['arrive_min']); loc=t['end_location']
for rr in reserves:
    cp=int(rr['checkpoint_min']); need=int(rr['min_buses']); thr=float(rr['min_soc_kwh'])
    count=0
    for bus_id,bus in buses.items():
        seq=sorted(by_bus.get(bus_id,[]), key=lambda x:int(x['depart_min']))
        if not seq:
            if float(bus['initial_soc_kwh']) + 1e-8 >= thr:
                count += 1
            continue
        active=False; prev=None; nxt=None; soc=float(bus['initial_soc_kwh'])
        for t in seq:
            ds=int(t['depart_min']); ae=int(t['arrive_min'])
            if ds <= cp < ae:
                active=True; break
            if ae <= cp:
                prev=t; soc -= float(t['energy_kwh'])
            if cp < ds:
                nxt=t; break
        if active or soc + 1e-8 < thr:
            continue
        arrive=0 if prev is None else int(prev['arrive_min']) + dead[(prev['end_location'],'DEPOT')]
        leave=math.inf if nxt is None else int(nxt['depart_min']) - dead[('DEPOT',nxt['start_location'])]
        if arrive <= cp <= leave:
            count += 1
    if count < need:
        issues.append(f'reserve {cp} {count}<{need}')
print('external_issue_count', len(issues))
if issues:
    print('\\n'.join(issues[:20]))
    raise SystemExit(1)
